export function createMaterialControls({e,fileInput}){
 const hidden=(name,value)=>'<input type="hidden" name="'+name+'" value="'+e(value)+'">';
 const copyForm=(r,classes)=>{const targets=classes.filter(c=>c.id!==r.classId);return !r.archived&&targets.length?'<details class="vle-panel"><summary>Copy to another class</summary><form data-vle="resource-copy">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||1)+hidden('operationId',crypto.randomUUID())+'<label class="vle-field">Destination class<select name="targetClassId" aria-label="Copy material destination" required><option value="">Choose a class…</option>'+targets.map(c=>'<option value="'+e(c.id)+'">'+e(c.name)+'</option>').join('')+'</select></label><label class="vle-field">Copied material title<input name="title" maxlength="160" value="'+e(r.title)+'" required></label><p class="vle-note">The selected class will receive an independent copy, including the description, documents and optional link. Its students can access it immediately.</p><button type="submit" class="btn primary">Share copy to selected class</button></form></details>':'';};
 return (r,classes=[])=>'<div class="material-controls">'+(!r.archived?'<details class="vle-panel"><summary>Edit material</summary><form data-vle="resource-update">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||1)+'<div class="vle-form-grid"><label class="vle-field">Title<input name="title" maxlength="160" value="'+e(r.title)+'" required></label><label class="vle-field">Topic<input name="topic" maxlength="100" value="'+e(r.topic||'Class materials')+'"></label></div><label class="vle-field">Description<textarea name="body" maxlength="10000">'+e(r.body||'')+'</textarea></label><label class="vle-field">HTTPS link (optional)<input name="url" type="url" value="'+e(r.url||'')+'"></label><p>Leave files blank to keep the current attachments. New uploads replace all current attachments.</p>'+fileInput()+(r.files?.length?'<label class="community-check"><input type="checkbox" name="clearFiles"> Remove current attachments (when no replacement is uploaded)</label>':'')+'<button type="submit" class="btn primary">Save material changes</button></form></details>':'<p class="vle-note">Archived material is hidden from students. Restore it to make it available again.</p>')+copyForm(r,classes)+'<form data-vle="resource-archive">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||1)+hidden('archived',!r.archived)+'<button type="submit" class="btn">'+(r.archived?'Restore material':'Archive material')+'</button></form></div>';
}
